+static GSList *
+stack_pop(GSList *stack, dfvm_value_t *arg1)
+{
+	ws_assert(arg1->type == INTEGER);
+	unsigned count = arg1->value.numeric;
+
+	for (unsigned i = 0; i < count; i++) {
